export const MAP_MUSIC={'dexlabs-bunker':'tech-center','sector-v':'suburbia','camp-kidney':'woods','salvage-yard':'reactor-works','original-city':'midtown'};
export function musicFor(phase,mapId){return phase==='menu'?'main-theme':MAP_MUSIC[mapId]||'suburbia'}
export class OriginalMusic{
 constructor(ctx,destination,{fetchImpl=fetch}={}){this.ctx=ctx;this.destination=destination;this.fetch=fetchImpl;this.buffers=new Map();this.active=null;this.desired=null;this.pending=null;this.retryAt=0;this.generation=0;this.fading=new Set()}
 async catalog(){if(!this.catalogPromise)this.catalogPromise=this.fetch('assets/music-original/catalog.json').then(r=>{if(!r.ok)throw Error('Music catalog unavailable');return r.json()}).catch(e=>{this.catalogPromise=null;throw e});return this.catalogPromise}
 async buffer(id){if(this.buffers.has(id))return this.buffers.get(id);const catalog=await this.catalog(),entry=catalog.tracks[id];if(!entry)throw Error('Unknown music track');const response=await this.fetch(entry.url);if(!response.ok)throw Error('Music unavailable');const buffer=await this.ctx.decodeAudioData(await response.arrayBuffer());this.buffers.set(id,buffer);for(const key of this.buffers.keys())if(this.buffers.size>2&&key!==id&&key!==this.active?.id)this.buffers.delete(key);return buffer}
 update(phase,mapId,{paused=false,volume=1}={}){const id=musicFor(phase,mapId);if(this.desired!==id){this.desired=id;this.generation++;this.retryAt=0}if(paused||volume<=0||this.active?.id===id||this.pending===id||this.ctx.currentTime<this.retryAt)return;void this.select(id)}
 async select(id){const generation=this.generation;this.pending=id;try{const buffer=await this.buffer(id);if(generation!==this.generation||this.desired!==id)return;const t=this.ctx.currentTime,source=this.ctx.createBufferSource(),gain=this.ctx.createGain();source.buffer=buffer;source.loop=true;source.loopStart=0;source.loopEnd=buffer.duration;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(1,t+.8);source.connect(gain).connect(this.destination);const next={id,source,gain};source.onended=()=>{source.disconnect();gain.disconnect();this.fading.delete(next)};source.start(t);
   if(this.active){const old=this.active;old.gain.gain.cancelScheduledValues(t);old.gain.gain.setValueAtTime(old.gain.gain.value,t);old.gain.gain.linearRampToValueAtTime(0,t+.8);old.source.stop(t+.85);this.fading.add(old)}this.active=next;
  }catch{this.retryAt=this.ctx.currentTime+5}finally{if(this.pending===id)this.pending=null}}
 dispose(){this.generation++;this.desired=null;for(const item of [this.active,...this.fading])if(item){try{item.source.stop()}catch{}item.source.disconnect();item.gain.disconnect()}this.active=null;this.fading.clear();this.buffers.clear()}
}
